import asyncio

from rclpy.task import Future as RosFuture
from std_msgs.msg import String

import asyncio_for_robotics.ros2 as afor

TOPIC = afor.TopicInfo(msg_type=String, topic="example/talker")


async def wait_robot_ready(robot):
    sub = robot.robot_state_sub
    async for state_msg in sub.listen():
        if state_msg == READY:
            return


def ros(robot):
    ros_node = robot.ros_node
    robot_ready_future = RosFuture()

    def ready_cbk(msg):
        if msg != READY:
            return
        if not robot_ready_future.done():
            robot_ready_future.set_result(msg)

    robot_state_sub = ros_node.create_subscription(TOPIC, ready_cbk)
    robot_ready_future.add_done_callback(
        ros_node.destroy_subscription(robot_state_sub)
    )
    return robot_ready_future
